@gene("new", "value of casting an ability: damage/cc on champions or camps, heal/shield when hurt", parents=["s1"])
def cast_value(o: Option) -> Num:
    k = slot_kind(o.slot)
    if k == AB_HEAL or k == AB_SHIELD:
